package com.example.starter_project_2025.system.project.backlog_temp;

import com.example.starter_project_2025.base.crud.mapper.BaseCrudMapper;
import com.example.starter_project_2025.base.crud.mapper.BaseMapperConfig;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;

/**
 * Task has no JPA relations (the referenced modules are external), so plain
 * field name mapping is enough.
 */
@Mapper(componentModel = "spring", config = BaseMapperConfig.class)
public interface TaskMapper extends BaseCrudMapper<Task, TaskDTO> {

    /**
     * The id is generated by the database, never taken from the request.
     */
    @Override
    @Mapping(target = "id", ignore = true)
    Task toEntity(TaskDTO request);
}
